"""Demo 1: The cognitive-power order and the mind-tool relation.

Models formal systems as sets of theorems (statements = frozensets of naturals),
and verifies the extension order, the strict mind-tool relation, transitivity,
and irreflexivity on concrete examples.
"""
from __future__ import annotations
from typing import FrozenSet, Set

Statement = FrozenSet[int]
System = Set[Statement]

def le_pow(f: System, g: System) -> bool:
    return f.issubset(g)

def lt_pow(f: System, g: System) -> bool:
    return f.issubset(g) and f != g

def is_mind_tool(brain: System, tool: System) -> bool:
    return lt_pow(brain, tool)

def main() -> None:
    brain: System = {frozenset({0}), frozenset({1})}
    tool:  System = {frozenset({0}), frozenset({1}), frozenset({2, 3})}
    bigger = tool | {frozenset({4})}
    print("brain <= tool     :", le_pow(brain, tool))
    print("tool is mind tool :", is_mind_tool(brain, tool))
    print("transitivity      :",
          is_mind_tool(brain, tool) and is_mind_tool(tool, bigger)
          and is_mind_tool(brain, bigger))
    print("irreflexivity     :", is_mind_tool(brain, brain))

if __name__ == "__main__":
    main()

"""Demo 3: Categorical dominance over set-level, instance-by-instance work.

prob(n) = {n} encodes 'the problem for object n'. A set-level system solves a
finite batch; the categorical system solves the whole family from one universal
theorem. The set-level system is always a strict subset — no finite catch-up.
"""
from __future__ import annotations
from typing import FrozenSet, Iterable, Set

Statement = FrozenSet[int]
System = Set[Statement]

def prob(n: int) -> Statement:
    return frozenset({n})

def set_level(solved: Iterable[int]) -> System:
    return {prob(n) for n in solved}

def cat_level(bound: int) -> System:
    return {prob(n) for n in range(bound)}

def main() -> None:
    S = set_level([0, 1, 2, 5, 9])
    C = cat_level(12)
    print("Set proves 7?     :", prob(7) in S)
    print("Cat proves 7?     :", prob(7) in C)
    print("Set < Cat         :", S.issubset(C) and S != C)
    print("|Set| finite      :", len(S), "; Cat unbounded")

if __name__ == "__main__":
    main()

