function diagonal_missing(listing, N):
    D <- empty set
    for i in 0 .. N-1:
        e_i <- listing[i] if i < len(listing) else empty set
        if i not in e_i:      # force D to differ from e_i at point i
            add i to D
    return D                  # D != e(i) for all i < N

function extend(brain, D):
    return brain union {D}    # strictly larger: brain < result

