from __future__ import annotations
from typing import FrozenSet, List, Set

Statement = FrozenSet[int]
System = Set[Statement]

def diagonal_missing(listing: List[Statement], n: int) -> Statement:
    built: Set[int] = set()
    for i in range(n):
        e_i = listing[i] if i < len(listing) else frozenset()
        if i not in e_i:
            built.add(i)
    return frozenset(built)

def extend(brain: System, d: Statement) -> System:
    return set(brain) | {d}

algorithms.pseudocode:
function tail_system(n, top):
    return { {m} : n <= m < top }          # theorems are singletons {m}, m>=n

function descending_chain(top):
    chain <- [ tail_system(n, top) for n in 0 .. top-1 ]
    strict <- true
    for n in 0 .. top-2:
        strict <- strict and (chain[n+1] subset of chain[n]) and (chain[n+1] != chain[n])
    return chain, strict                    # strict = True => not well-founded

